BehaviorPathPlannerNode::BehaviorPathPlannerNode(const rclcpp::NodeOptions & node_options)
: Node("behavior_path_planner", node_options),
  planning_factor_interface_(std::make_unique<PlanningFactorInterface>(this, "behavior_path_planner"))
{
  using std::placeholders::_1;
  using std::chrono_literals::operator""ms;

  // data_manager
  {
    planner_data_ = std::make_shared<PlannerData>();
    planner_data_->init_parameters(*this);
  }

  // publisher
  path_publisher_ = create_publisher<PathWithLaneId>("~/output/path", 1);
  turn_signal_publisher_ =
    create_publisher<TurnIndicatorsCommand>("~/output/turn_indicators_cmd", 1);
  hazard_signal_publisher_ = create_publisher<HazardLightsCommand>("~/output/hazard_lights_cmd", 1);
  const auto durable_qos = rclcpp::QoS(1).transient_local();
  modified_goal_publisher_ =
    create_publisher<PoseWithUuidStamped>("~/output/modified_goal", durable_qos);
  reroute_availability_publisher_ =
    create_publisher<RerouteAvailability>("~/output/is_reroute_available", 1);

  debug_avoidance_msg_array_publisher_ =
    create_publisher<AvoidanceDebugMsgArray>("~/debug/avoidance_debug_message_array", 1);

  debug_start_planner_evaluation_table_publisher_ptr_ =
    std::make_unique<DebugPublisher>(this, "~/debug/start_planner_evaluation_table");

  debug_turn_signal_info_publisher_ = create_publisher<MarkerArray>("~/debug/turn_signal_info", 1);

  bound_publisher_ = create_publisher<MarkerArray>("~/debug/bound", 1);

  {
    const std::string path_candidate_name_space = "/planning/path_candidate/";
    const std::string path_reference_name_space = "/planning/path_reference/";

    const std::lock_guard<std::mutex> lock(mutex_manager_);  // for planner_manager_

    const auto slots = declare_parameter<std::vector<std::string>>("slots");
    /* cppcheck-suppress syntaxError */
    std::vector<std::vector<std::string>> slot_configuration{slots.size()};
    for (size_t i = 0; i < slots.size(); ++i) {
      const auto & slot = slots.at(i);
      const auto modules = declare_parameter<std::vector<std::string>>(slot);
      for (const auto & module_name : modules) {
        slot_configuration.at(i).push_back(module_name);
      }
    }

    planner_manager_ = std::make_shared<PlannerManager>(*this);

    for (const auto & name : declare_parameter<std::vector<std::string>>("launch_modules")) {
      // workaround: Since ROS 2 can't get empty list, launcher set [''] on the parameter.
      if (name == "") {
        break;
      }
      planner_manager_->launchScenePlugin(*this, name);
    }

    // NOTE: this needs to be after launchScenePlugin()
    planner_manager_->configureModuleSlot(slot_configuration);

    for (const auto & manager : planner_manager_->getSceneModuleManagers()) {
      path_candidate_publishers_.emplace(
        manager->name(), create_publisher<Path>(path_candidate_name_space + manager->name(), 1));
      path_reference_publishers_.emplace(
        manager->name(), create_publisher<Path>(path_reference_name_space + manager->name(), 1));
    }
  }

  m_set_param_res = this->add_on_set_parameters_callback(
    std::bind(&BehaviorPathPlannerNode::onSetParam, this, std::placeholders::_1));

  // turn signal decider
  {
    const double turn_signal_intersection_search_distance =
      planner_data_->parameters.turn_signal_intersection_search_distance;
    const double turn_signal_intersection_angle_threshold_deg =
      planner_data_->parameters.turn_signal_intersection_angle_threshold_deg;
    const double turn_signal_search_time = planner_data_->parameters.turn_signal_search_time;
    const std::string turn_signal_roundabout_on_entry =
      planner_data_->parameters.turn_signal_roundabout_on_entry;
    const std::string turn_signal_roundabout_on_exit =
      planner_data_->parameters.turn_signal_roundabout_on_exit;
    const bool turn_signal_roundabout_entry_indicator_persistence =
      planner_data_->parameters.turn_signal_roundabout_entry_indicator_persistence;
    const double turn_signal_roundabout_search_distance =
      planner_data_->parameters.turn_signal_roundabout_search_distance;
    const double turn_signal_roundabout_angle_threshold_deg =
      planner_data_->parameters.turn_signal_roundabout_angle_threshold_deg;
    const int turn_signal_roundabout_backward_depth =
      planner_data_->parameters.turn_signal_roundabout_backward_depth;
    planner_data_->turn_signal_decider.setParameters(
      planner_data_->parameters.base_link2front, turn_signal_intersection_search_distance,
      turn_signal_search_time, turn_signal_intersection_angle_threshold_deg,
      turn_signal_roundabout_on_entry, turn_signal_roundabout_on_exit,
      turn_signal_roundabout_entry_indicator_persistence, turn_signal_roundabout_search_distance,
      turn_signal_roundabout_angle_threshold_deg, turn_signal_roundabout_backward_depth);
  }

  // Start timer
  {
    const auto planning_hz = declare_parameter<double>("planning_hz");
    const auto period_ns = rclcpp::Rate(planning_hz).period();
    timer_ = rclcpp::create_timer(
      this, get_clock(), period_ns, std::bind(&BehaviorPathPlannerNode::run, this));
  }
  // Timeout handling
  {
    cyclic_message_timeout_ = declare_parameter<double>("cyclic_timeout");
    enable_traffic_signal_timeout_ = declare_parameter<bool>("enable_traffic_signal_timeout");
    diagnostics_message_timeout_ =
      std::make_unique<autoware_utils_diagnostics::DiagnosticsInterface>(
        this, "incoming_message_timeout");
  }

  logger_configure_ = std::make_unique<autoware_utils::LoggerLevelConfigure>(this);
  published_time_publisher_ = std::make_unique<autoware_utils::PublishedTimePublisher>(this);
}

void init_parameters(rclcpp::Node & node)
{
  parameters.traffic_light_signal_timeout =
    node.declare_parameter<double>("traffic_light_signal_timeout");

  // vehicle info
  const auto vehicle_info = autoware::vehicle_info_utils::VehicleInfoUtils(node).getVehicleInfo();
  parameters.vehicle_info = vehicle_info;
  parameters.vehicle_width = vehicle_info.vehicle_width_m;
  parameters.vehicle_length = vehicle_info.vehicle_length_m;
  parameters.wheel_tread = vehicle_info.wheel_tread_m;
  parameters.wheel_base = vehicle_info.wheel_base_m;
  parameters.front_overhang = vehicle_info.front_overhang_m;
  parameters.rear_overhang = vehicle_info.rear_overhang_m;
  parameters.left_over_hang = vehicle_info.left_overhang_m;
  parameters.right_over_hang = vehicle_info.right_overhang_m;
  parameters.base_link2front = vehicle_info.max_longitudinal_offset_m;
  parameters.base_link2rear = parameters.rear_overhang;

  // NOTE: backward_path_length is used not only calculating path length but also calculating the
  // size of a drivable area.
  //       The drivable area has to cover not the base link but the vehicle itself. Therefore
  //       rear_overhang must be added to backward_path_length. In addition, because of the
  //       calculation of the drivable area in the autoware_path_optimizer package, the drivable
  //       area has to be a little longer than the backward_path_length parameter by adding
  //       min_backward_offset.
  constexpr double min_backward_offset = 1.0;
  const double backward_offset = vehicle_info.rear_overhang_m + min_backward_offset;

  // ROS parameters
  parameters.backward_path_length =
    node.declare_parameter<double>("backward_path_length") + backward_offset;
  parameters.forward_path_length = node.declare_parameter<double>("forward_path_length");

  // acceleration parameters
  parameters.min_acc = node.declare_parameter<double>("normal.min_acc");
  parameters.max_acc = node.declare_parameter<double>("normal.max_acc");

  parameters.max_vel = node.declare_parameter<double>("max_vel");
  parameters.backward_length_buffer_for_end_of_pull_over =
    node.declare_parameter<double>("backward_length_buffer_for_end_of_pull_over");
  parameters.backward_length_buffer_for_end_of_pull_out =
    node.declare_parameter<double>("backward_length_buffer_for_end_of_pull_out");

  parameters.minimum_pull_over_length =
    node.declare_parameter<double>("minimum_pull_over_length");
  parameters.refine_goal_search_radius_range =
    node.declare_parameter<double>("refine_goal_search_radius_range");
  parameters.turn_signal_intersection_search_distance =
    node.declare_parameter<double>("turn_signal_intersection_search_distance");
  parameters.turn_signal_intersection_angle_threshold_deg =
    node.declare_parameter<double>("turn_signal_intersection_angle_threshold_deg");
  parameters.turn_signal_minimum_search_distance =
    node.declare_parameter<double>("turn_signal_minimum_search_distance");
  parameters.turn_signal_search_time = node.declare_parameter<double>("turn_signal_search_time");
  parameters.turn_signal_shift_length_threshold =
    node.declare_parameter<double>("turn_signal_shift_length_threshold");
  parameters.turn_signal_remaining_shift_length_threshold =
    node.declare_parameter<double>("turn_signal_remaining_shift_length_threshold");
  parameters.turn_signal_remaining_distance_to_bound_threshold =
    node.declare_parameter<double>("turn_signal_remaining_distance_to_bound_threshold");
  parameters.turn_signal_on_swerving = node.declare_parameter<bool>("turn_signal_on_swerving");
  parameters.turn_signal_roundabout_on_entry =
    node.declare_parameter<std::string>("turn_signal_roundabout_on_entry");
  parameters.turn_signal_roundabout_on_exit =
    node.declare_parameter<std::string>("turn_signal_roundabout_on_exit");
  parameters.turn_signal_roundabout_entry_indicator_persistence =
    node.declare_parameter<bool>("turn_signal_roundabout_entry_indicator_persistence");
  parameters.turn_signal_roundabout_search_distance =
    node.declare_parameter<double>("turn_signal_roundabout_search_distance");
  parameters.turn_signal_roundabout_angle_threshold_deg =
    node.declare_parameter<double>("turn_signal_roundabout_angle_threshold_deg");
  parameters.turn_signal_roundabout_backward_depth =
    node.declare_parameter<int>("turn_signal_roundabout_backward_depth");
  parameters.turn_signal_path_backward_length =
    node.declare_parameter<double>("turn_signal_path_backward_length");

  parameters.enable_akima_spline_first =
    node.declare_parameter<bool>("enable_akima_spline_first");
  parameters.enable_cog_on_centerline = node.declare_parameter<bool>("enable_cog_on_centerline");
  parameters.input_path_interval = node.declare_parameter<double>("input_path_interval");
  parameters.output_path_interval = node.declare_parameter<double>("output_path_interval");
  parameters.ego_nearest_dist_threshold =
    node.declare_parameter<double>("ego_nearest_dist_threshold");
  parameters.ego_nearest_yaw_threshold =
    node.declare_parameter<double>("ego_nearest_yaw_threshold");

  drivable_area_expansion_parameters.init(node);
}

void init(rclcpp::Node & node)
{
  drivable_area_right_bound_offset =
    node.declare_parameter<double>(DRIVABLE_AREA_RIGHT_BOUND_OFFSET_PARAM);
  drivable_area_left_bound_offset =
    node.declare_parameter<double>(DRIVABLE_AREA_LEFT_BOUND_OFFSET_PARAM);
  drivable_area_types_to_skip =
    node.declare_parameter<std::vector<std::string>>(DRIVABLE_AREA_TYPES_TO_SKIP_PARAM);
  enabled = node.declare_parameter<bool>(ENABLED_PARAM);
  max_expansion_distance = node.declare_parameter<double>(MAX_EXP_DIST_PARAM);
  extra_front_overhang = node.declare_parameter<double>(EGO_EXTRA_FRONT_OVERHANG);
  extra_wheelbase = node.declare_parameter<double>(EGO_EXTRA_WHEELBASE);
  extra_width = node.declare_parameter<double>(EGO_EXTRA_WIDTH);
  curvature_average_window = node.declare_parameter<int>(SMOOTHING_CURVATURE_WINDOW_PARAM);
  max_bound_rate = node.declare_parameter<double>(SMOOTHING_MAX_BOUND_RATE_PARAM);
  arc_length_range = node.declare_parameter<double>(SMOOTHING_ARC_LENGTH_RANGE_PARAM);
  max_path_arc_length = node.declare_parameter<double>(MAX_PATH_ARC_LENGTH_PARAM);
  resample_interval = node.declare_parameter<double>(RESAMPLE_INTERVAL_PARAM);
  max_reuse_deviation = node.declare_parameter<double>(MAX_REUSE_DEVIATION_PARAM);
  object_exclusion.exclude_static = node.declare_parameter<bool>(AVOID_STA_OBJECTS_PARAM);
  object_exclusion.exclude_dynamic = node.declare_parameter<bool>(AVOID_DYN_OBJECTS_PARAM);
  object_exclusion.stopped_obj_vel_th = node.declare_parameter<double>(STOPPED_OBJ_VEL_THRESH);
  object_exclusion.front_offset = node.declare_parameter<double>(OBJECTS_SAFE_MARGIN_FRONT);
  object_exclusion.rear_offset = node.declare_parameter<double>(OBJECTS_SAFE_MARGIN_REAR);
  object_exclusion.left_offset = node.declare_parameter<double>(OBJECTS_SAFE_MARGIN_LEFT);
  object_exclusion.right_offset = node.declare_parameter<double>(OBJECTS_SAFE_MARGIN_RIGHT);
  const auto raw_linestring_types =
    node.declare_parameter<std::vector<std::string>>(AVOID_LINESTRING_TYPES_PARAM);
  for (const auto & raw_ls_type : raw_linestring_types) {
    avoid_linestring_types.emplace_back(raw_ls_type);
  }
  avoid_linestring_dist = node.declare_parameter<double>(AVOID_LINESTRING_DIST_PARAM);
  min_bound_interval = node.declare_parameter<double>(MIN_BOUND_INTERVAL);
  print_runtime = node.declare_parameter<bool>(PRINT_RUNTIME_PARAM);

  vehicle_info = autoware::vehicle_info_utils::VehicleInfoUtils(node).getVehicleInfo();
}

void PlannerManager::launchScenePlugin(rclcpp::Node & node, const std::string & name)
{
  if (plugin_loader_.isClassAvailable(name)) {
    const auto plugin = plugin_loader_.createSharedInstance(name);
    plugin->init(&node);

    // Check if the plugin is already registered.
    for (const auto & running_plugin : manager_ptrs_) {
      if (plugin->name() == running_plugin->name()) {
        RCLCPP_WARN_STREAM(node.get_logger(), "The plugin '" << name << "' is already loaded.");
        return;
      }
    }

    // register
    manager_ptrs_.push_back(plugin);
    processing_time_.emplace(plugin->name(), 0.0);
    RCLCPP_DEBUG_STREAM(node.get_logger(), "The scene plugin '" << name << "' is loaded.");
  } else {
    RCLCPP_ERROR_STREAM(node.get_logger(), "The scene plugin '" << name << "' is not available.");
  }
}

void BidirectionalTrafficModuleParameters::init_from_node(rclcpp::Node * node, std::string_view ns)
{
  time_to_prepare_pull_over =
    node->declare_parameter<double>(std::string(ns) + ".time_to_prepare_pull_over");
  min_distance_from_roadside =
    node->declare_parameter<double>(std::string(ns) + ".min_distance_from_roadside");
  keep_left_distance_from_center_line =
    node->declare_parameter<double>(std::string(ns) + ".keep_left_distance_from_center_line");
  shift_distance_to_pull_over_from_center_line = node->declare_parameter<double>(
    std::string(ns) + ".shift_distance_to_pull_over_from_center_line");
  wait_time_for_oncoming_car =
    node->declare_parameter<double>(std::string(ns) + ".wait_time_for_oncoming_car");
  max_lateral_jerk = node->declare_parameter<double>(std::string(ns) + ".max_lateral_jerk");
  min_lateral_jerk = node->declare_parameter<double>(std::string(ns) + ".min_lateral_jerk");
}

void PlannerManager::configureModuleSlot(
  const std::vector<std::vector<std::string>> & slot_configuration)
{
  std::unordered_map<std::string, SceneModuleManagerPtr> registered_modules;
  for (const auto & manager_ptr : manager_ptrs_) {
    registered_modules[manager_ptr->name()] = manager_ptr;
  }

  for (const auto & slot : slot_configuration) {
    SubPlannerManager sub_manager(current_route_lanelet_, processing_time_, debug_info_);
    for (const auto & module_name : slot) {
      if (const auto it = registered_modules.find(module_name); it != registered_modules.end()) {
        sub_manager.addSceneModuleManager(it->second);
      } else {
        // TODO(Mamoru Sobue): use LOG
        std::cout << module_name << " registered in slot_configuration is not registered, skipping"
                  << std::endl;
      }
    }
    if (sub_manager.getSceneModuleManager().size() != 0) {
      planner_manager_slots_.push_back(sub_manager);
      // TODO(Mamoru Sobue): use LOG
      std::cout << "added a slot with " << sub_manager.getSceneModuleManager().size() << " modules"
                << std::endl;
    }
  }
}

void addSceneModuleManager(const SceneModuleManagerPtr module_ptr)
{
  manager_ptrs_.push_back(module_ptr);
  // NOTE(Mamoru Sobue): SceneModuleManagerPtr->name() == SceneModulePtr->name()
  module_priorities_[module_ptr->name()] = module_priorities_.size();
}

void setParameters(
  const double base_link2front, const double intersection_search_distance,
  const double turn_signal_search_time, const double intersection_angle_threshold_deg,
  const std::string roundabout_on_entry, const std::string roundabout_on_exit,
  const bool roundabout_entry_indicator_persistence, const double roundabout_search_distance,
  const double roundabout_angle_threshold_deg, const int roundabout_backward_depth)
{
  base_link2front_ = base_link2front;
  intersection_search_distance_ = intersection_search_distance;
  turn_signal_search_time_ = turn_signal_search_time;
  intersection_angle_threshold_deg_ = intersection_angle_threshold_deg;
  if (roundabout_on_entry == "Left") {
    roundabout_on_entry_ = TurnIndicatorsCommand::ENABLE_LEFT;
  } else if (roundabout_on_entry == "Right") {
    roundabout_on_entry_ = TurnIndicatorsCommand::ENABLE_RIGHT;
  } else {
    roundabout_on_entry_ = TurnIndicatorsCommand::DISABLE;
  }
  if (roundabout_on_exit == "Left") {
    roundabout_on_exit_ = TurnIndicatorsCommand::ENABLE_LEFT;
  } else if (roundabout_on_exit == "Right") {
    roundabout_on_exit_ = TurnIndicatorsCommand::ENABLE_RIGHT;
  } else {
    roundabout_on_exit_ = TurnIndicatorsCommand::DISABLE;
  }
  roundabout_entry_indicator_persistence_ = roundabout_entry_indicator_persistence;
  roundabout_search_distance_ = roundabout_search_distance;
  roundabout_angle_threshold_deg_ = roundabout_angle_threshold_deg;
  roundabout_backward_depth_ = roundabout_backward_depth;
}
